import { useEffect, useState } from 'react'
import { Button } from '@/components/ui'
import { upperAz } from '@/lib/text'
import type { CodePage } from '@/types'

type CopyState = 'idle' | 'copied' | 'failed'

/** Code is rendered as text and never executed. Line numbers are generated by CSS, so copy returns the exact source. */
export function CodePageRenderer({ page }: { page: CodePage }) {
  const [copy, setCopy] = useState<CopyState>('idle')

  useEffect(() => {
    if (copy === 'idle') return
    const timer = window.setTimeout(() => setCopy('idle'), 2500)
    return () => window.clearTimeout(timer)
  }, [copy])

  const onCopy = async () => {
    try {
      await navigator.clipboard.writeText(page.code)
      setCopy('copied')
    } catch {
      setCopy('failed')
    }
  }

  return (
    <div className="max-w-3xl">
      {page.description && <p className="mb-4 max-w-[68ch] leading-7">{page.description}</p>}
      <div className="overflow-hidden rounded-lg border border-line-strong bg-bg">
        <div className="panel-bar">
          <span className="label flex items-center gap-2">
            {(page.language === 'bash' || page.language === 'shell') && <span aria-hidden="true" className="text-accent">$</span>}
            {upperAz(page.language)}
          </span>
          <div className="flex items-center gap-2">
            <span role="status" className="text-xs text-fg-muted">
              {copy === 'copied' && 'Kopyalandı'}
              {copy === 'failed' && 'Kopyalamaq mümkün olmadı'}
            </span>
            <Button variant="ghost" size="sm" onClick={onCopy} aria-label="Kodu kopyala">Kopyala</Button>
          </div>
        </div>
        <pre tabIndex={0} role="region" aria-label={`Kod: ${page.language}`} className="code-lines overflow-x-auto py-4 pr-4 font-mono text-sm leading-6">
          <code>{page.code.split('\n').map((line, i) => <span key={i} className="code-line">{line}</span>)}</code>
        </pre>
      </div>
    </div>
  )
}
